CREATE OR REPLACE FUNCTION calculate_sustainability_index(equip_code VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    efficiency_val REAL;
    power_src TEXT;
    multiplier REAL;
BEGIN
    -- Get efficiency index from equipment
    SELECT efficiencyindex INTO efficiency_val
    FROM equipment
    WHERE equipmentcode = equip_code;

    -- Get power source from powerbattery
    SELECT powersource INTO power_src
    FROM powerbattery
    WHERE pwrbatteqref = equip_code;

    -- Determine multiplier based on power source
    CASE power_src
        WHEN 'Solar' THEN multiplier := 1.5;
        WHEN 'Wind' THEN multiplier := 1.5;
        WHEN 'Hybrid' THEN multiplier := 1.2;
        WHEN 'Battery' THEN multiplier := 1.0;
        WHEN 'Diesel' THEN multiplier := 0.7;
        ELSE multiplier := 1.0;
    END CASE;

    RETURN efficiency_val * multiplier;
END;
$$ LANGUAGE plpgsql;

